import { IMail } from './mail.service';

/** Application name shown in the message. */
export function otpBrandName(env: NodeJS.ProcessEnv = process.env): string {
  return (env.APP_NAME || 'Orion').replace(/[\r\n<>]/g, '').slice(0, 60) || 'Orion';
}

/**
 * The sign-up code e-mail. `code` is six digits generated by the server and `minutes` a number, so nothing user-supplied is interpolated;
 * the brand name comes from configuration and is stripped of markup and line breaks. Marked `sensitive`: the body is never logged.
 */
export function buildEmailOtpMail(to: string, code: string, minutes: number, env: NodeJS.ProcessEnv = process.env): IMail {
  const brand = otpBrandName(env);
  const spaced = `${code.slice(0, 3)} ${code.slice(3)}`;
  const text = [
    `Your ${brand} verification code is ${code}.`,
    '',
    `It expires in ${minutes} minutes and can be used once.`,
    'Never share this code with anyone. We will never ask you for it by phone, chat or e-mail.',
    '',
    `If you did not try to create a ${brand} account, you can ignore this message; nothing was created.`,
  ].join('\n');
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${brand} verification code</title></head>
<body style="margin:0;padding:0;background:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#18181b;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:32px 16px;"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:480px;background:#ffffff;border:1px solid #e4e4e7;border-radius:12px;">
<tr><td style="padding:28px 32px 8px 32px;font-size:18px;font-weight:700;">${brand}</td></tr>
<tr><td style="padding:8px 32px 0 32px;font-size:15px;line-height:1.6;color:#3f3f46;">Use this code to verify your email address and finish creating your account:</td></tr>
<tr><td align="center" style="padding:24px 32px;"><div style="display:inline-block;padding:14px 24px;background:#fafafa;border:1px solid #e4e4e7;border-radius:10px;font-size:32px;font-weight:700;letter-spacing:8px;font-family:'SFMono-Regular',Consolas,monospace;">${spaced}</div></td></tr>
<tr><td style="padding:0 32px 8px 32px;font-size:14px;line-height:1.6;color:#52525b;">This code expires in <strong>${minutes} minutes</strong> and can be used only once.</td></tr>
<tr><td style="padding:0 32px 24px 32px;font-size:14px;line-height:1.6;color:#b91c1c;"><strong>Do not share this code with anyone.</strong> We will never ask you for it.</td></tr>
<tr><td style="padding:16px 32px 28px 32px;border-top:1px solid #f4f4f5;font-size:12px;line-height:1.6;color:#a1a1aa;">If you did not try to create a ${brand} account, you can ignore this message. Nothing was created.</td></tr>
</table></td></tr></table></body></html>`;
  return { to, subject: `${brand}: your verification code`, text, html, sensitive: true };
}
